import { NextResponse } from "next/server";
import { TenraiAnime, TenraiManga } from "@/lib/Tenrai";
import IGDB from "@/lib/IGDB";
import GoogleBooks from "@/lib/GoogleBooks";
import { TMDBMovie, TMDBSerie } from "@/lib/TMDB";
import Deezer from "@/lib/Deezer";

export async function POST(req: Request){

    try{
        const { query } = await req.json();

        let anime, manga, game, book, music, serie, movie = null
        let searchVar;
        const encodeQuery = encodeURIComponent(query);

        const suggestions = []

        searchVar = await TenraiAnime(encodeQuery);
        
        if (searchVar){
            anime = await searchVar.json();
            anime = anime.info.title
            suggestions.push({name: anime, type: 'anime'})
        }else{
            anime = null
        }

        searchVar = await TenraiManga(encodeQuery);
        
        if (searchVar){
            manga = await searchVar.json();
            manga = manga.info.title
            suggestions.push({name: manga, type: 'manga'})
        }else{
            manga = null
        }

        searchVar = await IGDB(encodeQuery);
        
        if (searchVar){
            game = await searchVar.json();
            game = game.info.title
            suggestions.push({name: game, type: 'game'})
        }else{
            game = null
        }

        searchVar = await IGDB(encodeQuery);
        
        if (searchVar){
            game = await searchVar.json();
            game = game.info.title
            suggestions.push({name: game, type: 'game'})
        }else{
            game = null
        }

        console.log(suggestions)

        return NextResponse.json({query})
    }catch(err){
        console.log(err)
        return NextResponse.json({
            message: `Error! ${err}`
        }, {status: 500})
    } 

} 